public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    // Check remainder 0
    if (count[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r == complement) {
            if (count[r] % 2 != 0) {
                return false;
            }
        } else if (r < complement) {
            if (count[r] != count[complement]) {
                return false;
            }
        }
    }
    return true;
}

