private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        boolean childHas = dfs(nei, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.merge(ch, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = freq.firstEntry();
        char last = entry.getKey();
        result.append(last);
        if (--entry.getValue() == 0) {
            freq.remove(last);
        } else {
            freq.put(last, entry.getValue());
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> next = freq.higherEntry(last);
            if (next == null) break;
            last = next.getKey();
            result.append(last);
            if (--next.getValue() == 0) {
                freq.remove(last);
            } else {
                freq.put(last, next.getValue());
            }
        }
        if (freq.isEmpty()) break;
        // Descending phase
        entry = freq.lastEntry();
        last = entry.getKey();
        result.append(last);
        if (--entry.getValue() == 0) {
            freq.remove(last);
        } else {
            freq.put(last, entry.getValue());
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> prev = freq.lowerEntry(last);
            if (prev == null) break;
            last = prev.getKey();
            result.append(last);
            if (--prev.getValue() == 0) {
                freq.remove(last);
            } else {
                freq.put(last, prev.getValue());
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k in reverse to avoid using the same element twice
        for (int k = Math.min(n / 2, n); k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

