public int minInsertions(String s) {
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of insertions needed so far
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                // need to insert a '(' before this ')'
                insertions++;
                balance++; // pretend we inserted '('
            }
            balance--; // match this ')'
        }
    }
    // any remaining unmatched '(' need a ')' each
    insertions += balance;
    return insertions;
}

