public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = nums[0];
    int minSum = nums[0];
    int currentMax = nums[0];
    int currentMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // 50 is enough for int range
    int size = 0;
    fibs[size++] = 1;
    fibs[size++] = 1;
    while (true) {
        int next = fibs[size - 1] + fibs[size - 2];
        if (next > k) {
            break;
        }
        fibs[size++] = next;
    }

    // Greedy subtraction from largest to smallest
    int count = 0;
    for (int i = size - 1; i >= 0 && k > 0; i--) {
        if (fibs[i] <= k) {
            k -= fibs[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    factors.addAll(large);
    if (k <= factors.size()) {
        return factors.get(k - 1);
    }
    return -1;
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(c - top) == 32) { // one is lowercase, the other uppercase of same letter
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

