private int dfs(int index, String s, java.util.Set<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int count = 1 + dfs(end, s, used);
            if (count > max) {
                max = count;
            }
            used.remove(sub);
        }
    }
    return max;
}

