public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    // Initialize all characters to 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // amount of value we still need to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // we can add at most 25 to 'a' to reach 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

