public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] hor = new int[m][n];
    int[][] ver = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                hor[i][j] = (j > 0 ? hor[i][j - 1] : 0) + 1;
                ver[i][j] = (i > 0 ? ver[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(hor[i][j], ver[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    while (value > 0) {
        long part = value % 1000;
        value /= 1000;
        if (value > 0) {
            sb.insert(0, String.format("%03d", part));
            sb.insert(0, '.');
        } else {
            sb.insert(0, Long.toString(part));
        }
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    // Precompute adjacency matrix
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            can[i][j] = r * r == sum;
        }
    }
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int fullMask = (1 << n) - 1;
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            long key = ((long) mask << 32) | (last + 1);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            if (mask == fullMask) return 1;
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (last != -1 && !can[last][i]) continue;
                // skip duplicates
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << i), i);
            }
            memo.put(key, count);
            return count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

