                count += applyAsInt(mask | (1 << i), i);
            }
            memo.put(key, count);
            return count;
        }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[i] < heights[stack[top]]) {
            int h = heights[stack[top--]];
            int width = top >= 0 ? i - stack[top] - 1 : i;
            long area = (long) h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top >= 0) {
        int h = heights[stack[top--]];
        int width = top >= 0 ? n - stack[top] - 1 : n;
        long area = (long) h * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    int len = s.length();
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = s.charAt(i) - '0';
    }
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    int result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    build(n, n, result);
    return result;
}

private static void build(int curLen, int totalLen, List<String> result) {
    if (curLen == 0) {
        result.add("");
        return;
    }
    if (curLen == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return;
    }
    List<String> sub = new ArrayList<>();
    build(curLen - 2, totalLen, sub);
    for (String s : sub) {
        if (curLen == totalLen) {
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        } else {
            result.add("0" + s + "0");
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        }
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Check that all points are distinct
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }

    // Compute cross product of vectors (p2 - p1) and (p3 - p1)
    int x1 = p2[0] - p1[0];
    int y1 = p2[1] - p1[1];
    int x2 = p3[0] - p1[0];
    int y2 = p3[1] - p1[1];

    return x1 * y2 - y1 * x2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int curr, int n, List<Integer> res) {
    res.add(curr);
    if (curr > n / 10) return; // if curr*10 > n, no children
    for (int d = 0; d <= 9; d++) {
        int next = curr * 10 + d;
        if (next > n) break;
        dfs(next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Trim leading/trailing spaces to avoid empty tokens at ends
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        return "";
    }
    String[] words = trimmed.split("\\s+");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder rev = new StringBuilder(word).reverse();
        result.append(rev);
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
